alter table public.ride_requests add column if not exists destination_latitude double precision, add column if not exists destination_longitude double precision, add column if not exists route_distance_km numeric(8,2), add column if not exists route_duration_minutes numeric(8,2), add column if not exists estimated_fare numeric(10,2);
create table if not exists public.driver_kyc(id uuid primary key default gen_random_uuid(),driver_id uuid not null unique references public.profiles(id) on delete cascade,license_path text not null,vehicle_rc_path text not null,insurance_path text not null,verification_status text not null default 'pending' check(verification_status in('pending','approved','rejected')),admin_note text,reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,submitted_at timestamptz not null default now());
alter table public.driver_kyc enable row level security; revoke all on public.driver_kyc from anon,public; grant select,insert,update on public.driver_kyc to authenticated;
drop policy if exists "driver reads own kyc" on public.driver_kyc; create policy "driver reads own kyc" on public.driver_kyc for select to authenticated using(driver_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
drop policy if exists "driver submits own kyc" on public.driver_kyc; create policy "driver submits own kyc" on public.driver_kyc for insert to authenticated with check(driver_id=(select auth.uid()) and verification_status='pending');
drop policy if exists "driver resubmits own kyc" on public.driver_kyc; create policy "driver resubmits own kyc" on public.driver_kyc for update to authenticated using(driver_id=(select auth.uid()) and verification_status in('pending','rejected')) with check(driver_id=(select auth.uid()) and verification_status='pending');
drop policy if exists "admin reviews driver kyc" on public.driver_kyc; create policy "admin reviews driver kyc" on public.driver_kyc for update to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('driver-kyc-private','driver-kyc-private',false,10485760,array['image/jpeg','image/png','application/pdf']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "drivers upload own kyc documents" on storage.objects; create policy "drivers upload own kyc documents" on storage.objects for insert to authenticated with check(bucket_id='driver-kyc-private' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists "drivers read own kyc documents" on storage.objects; create policy "drivers read own kyc documents" on storage.objects for select to authenticated using(bucket_id='driver-kyc-private' and ((storage.foldername(name))[1]=(select auth.uid())::text or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin')));
drop policy if exists "drivers update own kyc documents" on storage.objects; create policy "drivers update own kyc documents" on storage.objects for update to authenticated using(bucket_id='driver-kyc-private' and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='driver-kyc-private' and (storage.foldername(name))[1]=(select auth.uid())::text);
create table if not exists public.driver_push_tokens(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,token text not null,platform text not null default 'android',updated_at timestamptz not null default now(),unique(user_id,token));
alter table public.driver_push_tokens enable row level security; revoke all on public.driver_push_tokens from anon,public; grant select,insert,update,delete on public.driver_push_tokens to authenticated;
drop policy if exists "drivers manage own push tokens" on public.driver_push_tokens; create policy "drivers manage own push tokens" on public.driver_push_tokens for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
